package com.avizero.avidrive.api;

import com.avizero.avidrive.domain.*; import com.avizero.avidrive.repository.*; import com.avizero.avidrive.security.AuthUser; import jakarta.servlet.http.HttpServletResponse; import java.io.*; import java.nio.file.*; import java.util.*; import java.util.zip.*; import org.springframework.core.io.Resource; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;

@RestController @RequestMapping("/api/files") public class DownloadController {
 private final StoredFileRepository files; private final FolderRepository folders; public DownloadController(StoredFileRepository f,FolderRepository d){files=f;folders=d;}
 @GetMapping("/{id}/download") public ResponseEntity<?> download(@PathVariable Long id,Authentication a){StoredFile f=files.findById(id).filter(x->x.ownerId.equals(owner(a))).orElse(null);if(f==null)return error(404,"Файл не найден");Path p=safeStoragePath(f.storagePath);if(p==null||!Files.isRegularFile(p))return error(404,"Файл не найден");try{Resource r=new org.springframework.core.io.FileSystemResource(p);return ResponseEntity.ok().contentType(MediaType.APPLICATION_OCTET_STREAM).header("X-Content-Type-Options","nosniff").header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.attachment().filename(f.name).build().toString()).body(r);}catch(Exception e){return error(404,"Файл не найден");}}
 @PostMapping("/download-zip") public void zip(@RequestBody ZipRequest r,Authentication a,HttpServletResponse response)throws IOException{Long owner=owner(a);response.setContentType("application/zip");response.setHeader("X-Content-Type-Options","nosniff");response.setHeader(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\"archive.zip\"");try(ZipOutputStream out=new ZipOutputStream(response.getOutputStream())){for(Long id:r.file_ids()==null?List.<Long>of():r.file_ids()){files.findById(id).filter(x->x.ownerId.equals(owner)).ifPresent(f->addFile(out,f,f.name));}for(Long id:r.folder_ids()==null?List.<Long>of():r.folder_ids()){Folder folder=folders.findById(id).filter(x->x.ownerId.equals(owner)).orElse(null);if(folder!=null)addFolder(out,folder,"" );}}}
 private void addFolder(ZipOutputStream out,Folder folder,String prefix)throws IOException{String path=safe(prefix+folder.name)+"/";out.putNextEntry(new ZipEntry(path));out.closeEntry();for(Folder child:folders.findByOwnerIdAndParentId(folder.ownerId,folder.id))addFolder(out,child,path);for(StoredFile f:files.findByOwnerIdAndFolderId(folder.ownerId,folder.id))addFile(out,f,path+f.name);}
  private void addFile(ZipOutputStream out,StoredFile f,String name){try{Path p=safeStoragePath(f.storagePath);if(p==null||!Files.isRegularFile(p))return;String safe=safe(name);out.putNextEntry(new ZipEntry(safe));Files.copy(p,out);out.closeEntry();}catch(IOException ignored){try{out.closeEntry();}catch(IOException ignored2){}}}
  private Path safeStoragePath(String value){if(value==null)return null;Path root=Path.of("storage/files").toAbsolutePath().normalize();Path candidate=Path.of(value).toAbsolutePath().normalize();return candidate.startsWith(root)?candidate:null;}private String safe(String value){String normalized=value.replace('\\','/');while(normalized.startsWith("/"))normalized=normalized.substring(1);String[] parts=normalized.split("/");StringBuilder b=new StringBuilder();for(String part:parts)if(!part.isBlank()&&!part.equals(".")&&!part.equals("..")){if(b.length()>0)b.append('/');b.append(part.replaceAll("[\\\\:*?\"<>|]","_"));}return b.toString();} private Long owner(Authentication a){return ((AuthUser)a.getPrincipal()).id();}private ResponseEntity<Map<String,String>> error(int s,String m){return ResponseEntity.status(s).body(Map.of("message",m));}public record ZipRequest(List<Long> file_ids,List<Long> folder_ids){}
}
